{
  "application": "web-design",
  "case_id": "case-education-event-ideaforum-404",
  "language": "en",
  "site": {
    "type": "event",
    "page_count": 1,
    "audience": "general audience interested in educational conferences and talks",
    "tone": "minimal, professional",
    "responsive": true,
    "dark_mode": false
  },
  "brief": {
    "title": "IdeaForum — Page Not Found",
    "one_liner": "A 404 error page for an educational conference and talks platform, guiding users back to available content.",
    "goal": "Provide a clear, branded 404 error page that helps users navigate back to the main site or search for the content they were looking for."
  },
  "pages": [
    {
      "page_id": "error-404",
      "file": "index.html",
      "sections": [
        "hero-logo",
        "error-message",
        "search",
        "error-code",
        "next-steps"
      ],
      "objective": "Inform the user that the requested page was not found and provide helpful navigation options including search and links to the homepage and help center."
    }
  ],
  "navigation": [
    {
      "from": "error-404",
      "trigger": "Go to the homepage link",
      "to": "homepage"
    },
    {
      "from": "error-404",
      "trigger": "Visit our Help Desk link",
      "to": "help-desk"
    }
  ],
  "interactions": [
    {
      "id": "search-input",
      "page": "error-404",
      "trigger": "User types a query into the search input field and clicks the search icon",
      "expected": "A search is initiated and the user is taken to search results for their query",
      "type": "input"
    },
    {
      "id": "cookie-preferences",
      "page": "error-404",
      "trigger": "User clicks Manage Preferences in the cookie consent banner",
      "expected": "A modal or panel opens allowing the user to configure cookie and privacy preferences",
      "type": "toggle"
    }
  ],
  "data_display": [
    {
      "id": "error-details",
      "page": "error-404",
      "type": "list",
      "source_ref": "## Error Details",
      "expected_content": [
        "Sorry, we can't find that.",
        "Perhaps we can help you find the content you're looking for:",
        "HTTP Error 404",
        "What's next?",
        "Go to the homepage",
        "Visit our Help Desk"
      ],
      "description": "Error message content displayed on the 404 page including the apology, helpful suggestion, error code, and navigation links"
    }
  ]
}

